    // Broker: |read-committed fetches never see open or aborted transactions| [native] — ../src/contract.lawspec:173
    // While a transaction is open its records are past the last stable
    //       offset, which read-committed consumers do not pass. Once it aborts its
    //       records are skipped for ever. Read-uncommitted consumers see them both
    //       times.
    // References: KIP-98
    // for all (t :: Text) (txid :: Text) (batch :: List (lawtwin.kafka.model::type::Record)) => created t 1 implies transactionThenRead t txid batch false = true end for all
    private static Value LawBrokerReadCommittedFetchesNeverSeeOpenOr(
        Schema.Schema schema,
        Scalar.SymbolContext symbols,
        FSharpList<Value> inputs,
        FSharpList<Value> resources)
    {
        var t = Runtime.Item(0, inputs);
        var txid = Runtime.Item(1, inputs);
        var batch = Runtime.Item(2, inputs);
        var lawspecWithCluster = Runtime.Item(0, resources);
        if (Runtime.Truth(
            LawSpec.Generated.LawtwinKafka.Created(
                schema,
                symbols,
                t,
                Schema.Validate(V.Int(new BigInteger(1L)), Scalar.TypeOf("Int32"), schema))))
        {
            return Runtime.AssertEqual(
                LawSpec.Generated.LawtwinKafka.TransactionThenRead(
                    schema,
                    symbols,
                    t,
                    txid,
                    batch,
                    Schema.Validate(V.Bool(false), Scalar.TypeOf("Bool"), schema)),
                Schema.Validate(V.Bool(true), Scalar.TypeOf("Bool"), schema),
                "lawtwin.kafka::Broker: |read-committed fetches never see open or aborted transactions| [native] — ../src/contract.lawspec:173");
        }
        else
        {
            return V.Bool(true);
        }
    }

